const updateHomeroomAssignment = `-- name: UpdateHomeroomAssignment :one
WITH target AS (
    SELECT cha.id, cha.class_id
    FROM class_homeroom_assignments cha
    WHERE cha.id = $1
), deactivate_existing AS (
    UPDATE class_homeroom_assignments
    SET is_active = FALSE,
        updated_at = NOW()
    WHERE class_homeroom_assignments.class_id = (SELECT class_id FROM target)
      AND class_homeroom_assignments.id <> $1
      AND class_homeroom_assignments.is_active = TRUE
      AND $2::boolean = TRUE
    RETURNING class_homeroom_assignments.id
), updated AS (
    UPDATE class_homeroom_assignments
    SET employee_id = $3,
        is_active = $2,
        notes = $4,
        updated_at = NOW()
    WHERE class_homeroom_assignments.id = $1
    RETURNING id, class_id, employee_id, academic_year_id, start_date, end_date, is_active, notes, created_at, updated_at
)
SELECT
    updated.id,
    updated.class_id,
    c.code AS class_code,
    c.name AS class_name,
    updated.employee_id,
    e.nama AS employee_name,
    updated.academic_year_id,
    COALESCE(ay.name, '') AS academic_year_name,
    updated.start_date,
    updated.end_date,
    updated.is_active,
    updated.notes,
    updated.created_at,
    updated.updated_at
FROM updated
JOIN school_classes c ON c.id = updated.class_id
JOIN employees e ON e.id = updated.employee_id
LEFT JOIN academic_years ay ON ay.id = updated.academic_year_id
`

